+import test from "node:test";
+import assert from "node:assert/strict";
+import { openStore } from "../src/db/store.js";
+import { t } from "../src/i18n/messages.js";
+import { app, seed } from "./helpers.js";
+
+test("seed defines main and annex sites and locations", () => {
+  const data = seed();
+  assert.equal(data.schemaVersion, 3);
+  assert.deepEqual(data.sites, [
+    { id: "main", name: "Main kitchen" },
+    { id: "annex", name: "Annex kitchen" },
+  ]);
+  for (const id of ["fridge", "freezer", "dry"]) {
+    assert.equal(data.locations.find((l) => l.id === id).site, "main");
+  }
+  assert.deepEqual(data.locations.find((l) => l.id === "annex-fridge"), {
+    id: "annex-fridge",
+    name: "Annex fridge",
+    tempC: 4,
+    site: "annex",
+  });
+});
+
+test("older schema 2 data files still open", () => {
+  const store = openStore(new URL("../data/db.json", import.meta.url).pathname);
+  assert.equal(store.data.schemaVersion, 3);
+  assert.equal(store.data.locations.find((l) => l.id === "fridge").site, "main");
+});
+
+test("unknown X-Larder-Site returns 400 unknown_site", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "X-Larder-Site": "garden" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /garden/);
+  const empty = await handle({ path: "/items", headers: { "x-larder-site": "" } });
+  assert.equal(empty.status, 400);
+  assert.equal(empty.body.error.code, "unknown_site");
+  assert.match(t("unknown_site", "ko", { id: "garden" }), /garden/);
+});
+
+test("items, suppliers, recipes and dishes are shared across sites", async () => {
+  const { handle } = app();
+  const annex = { "X-Larder-Site": "annex" };
+  assert.equal((await handle({ path: "/items", headers: annex })).body.length, 6);
+  assert.equal((await handle({ path: "/suppliers", headers: annex })).body.length, 2);
+  assert.equal((await handle({ path: "/dishes", headers: annex })).body.length, 3);
+  assert.equal((await handle({ path: "/recipes/1/cost", headers: annex })).status, 200);
+});
+
+test("batches, stock on hand, cooking, alerts, stock value and stock-takes are site-scoped", async () => {
+  const { handle, store } = app();
+  const annex = { "X-Larder-Site": "annex" };
+
+  // Receive stock into annex-fridge for recipe 2 (milk, butter, flour)
+  const order = (
+    await handle({
+      method: "POST",
+      path: "/orders",
+      headers: annex,
+      body: {
+        supplierId: 1,
+        lines: [
+          { itemId: 2, qty: 3 },
+          { itemId: 3, qty: 1 },
+          { itemId: 4, qty: 1 },
+        ],
+      },
+    })
+  ).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send`, headers: annex });
+  const received = await handle({
+    method: "POST",
+    path: `/orders/${order.id}/receive`,
+    headers: annex,
+    body: {
+      lots: [
+        { lot: "AX-MILK", expires: "2026-10-30", location: "annex-fridge" },
+        { lot: "AX-BUTTER", expires: "2026-12-20", location: "annex-fridge" },
+        { lot: "AX-FLOUR", expires: "2027-03-30", location: "annex-fridge" },
+      ],
+    },
+  });
+  assert.equal(received.status, 200);
+  const annexMilkBatchId = received.body.batches[0].id;
+
+  // Stock on hand and batches
+  assert.equal((await handle({ path: "/items/2" })).body.onHand, 10);
+  assert.equal((await handle({ path: "/items/2", headers: annex })).body.onHand, 3);
+  assert.equal((await handle({ path: "/items/2", headers: annex })).body.batches.length, 1);
+  assert.equal((await handle({ path: "/batches" })).body.length, 9);
+  assert.equal((await handle({ path: "/batches", headers: annex })).body.length, 3);
+  assert.equal((await handle({ path: `/batches/${annexMilkBatchId}` })).status, 404);
+  assert.equal((await handle({ path: "/batches/1", headers: annex })).status, 404);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: annex, body: { qty: 1 } })).status, 404);
+
+  // Stock value report
+  const mainVal = (await handle({ path: "/reports/stock-value" })).body;
+  const annexVal = (await handle({ path: "/reports/stock-value", headers: annex })).body;
+  assert.equal(annexVal.totalCents, 3 * 129 + 1 * 945 + 1 * 85);
+  assert.notEqual(mainVal.totalCents, annexVal.totalCents);
+
+  // Alerts
+  const mainAlerts = (await handle({ path: "/alerts" })).body;
+  const annexAlerts = (await handle({ path: "/alerts", headers: annex })).body;
+  assert.equal(mainAlerts.expiring.some((b) => b.lot === "AX-MILK"), false);
+  assert.equal(annexAlerts.expiring.map((b) => b.lot).join(","), "AX-MILK");
+  assert.equal(mainAlerts.lowStock.length, 0);
+  assert.equal(annexAlerts.lowStock.length, 5);
+
+  // Cooking in annex uses only annex stock; recipe 1 needs onion/stock (0 in annex)
+  const failCook = await handle({ method: "POST", path: "/recipes/1/cook", headers: annex, body: { portions: 4 } });
+  assert.equal(failCook.status, 409);
+  const okCook = await handle({ method: "POST", path: "/recipes/2/cook", headers: annex, body: { portions: 10 } });
+  assert.equal(okCook.status, 200);
+  assert.equal((await handle({ path: "/items/2", headers: annex })).body.onHand, 1);
+  assert.equal((await handle({ path: "/items/2" })).body.onHand, 10);
+
+  // Stock-takes are site-scoped
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "annex-fridge" } })).status, 400);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "dry" } })).status, 400);
+
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "annex-fridge" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: annexMilkBatchId, counted: 2 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: annex, body: { batchId: 1, counted: 2 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 404);
+
+  await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: annex, body: { batchId: annexMilkBatchId, counted: 2 } });
+  const finished = await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: annex });
+  assert.equal(finished.status, 200);
+  assert.deepEqual(finished.body.lines, [{ batchId: annexMilkBatchId, expected: 1, counted: 2, diff: 1 }]);
+  assert.equal(store.data.batches.find((b) => b.id === annexMilkBatchId).qty, 2);
+});
